begin;

create temporary table imported_question_batch3_seed (
  id uuid primary key, certification_code text not null, lesson_slug text not null,
  question_type text not null, question_text text not null, difficulty text not null,
  explanation text not null, is_published boolean not null, source_reference text not null,
  source_order integer not null
) on commit drop;

create temporary table imported_question_option_batch3_seed (
  id uuid primary key, question_id uuid not null, option_text text not null,
  is_correct boolean not null, explanation text not null, display_order integer not null
) on commit drop;



do $$
declare invalid_slugs text;
begin
  select string_agg(invalid.lesson_slug, ', ' order by invalid.lesson_slug) into invalid_slugs
  from (
    select seed.lesson_slug
    from imported_question_batch3_seed seed
    left join public.lessons lesson on lesson.slug = seed.lesson_slug
    group by seed.lesson_slug
    having count(distinct lesson.id) <> 1
  ) invalid;
  if invalid_slugs is not null then raise exception 'lesson_slug ausente ou ambíguo: %', invalid_slugs; end if;
end
$$;

with resolved as (
  select seed.*, lesson.id as lesson_id, topic.id as topic_id,
    domain.id as domain_id, domain.certification_id
  from imported_question_batch3_seed seed
  join public.lessons lesson on lesson.slug = seed.lesson_slug
  join public.topics topic on topic.id = lesson.topic_id
  join public.domains domain on domain.id = topic.domain_id
),
new_seed as (
  select resolved.* from resolved
  where not exists (
    select 1 from public.questions existing
    where existing.id = resolved.id
       or (existing.lesson_id = resolved.lesson_id and lower(trim(existing.question_text)) = lower(trim(resolved.question_text)))
  )
),
ordered as (
  select new_seed.*, row_number() over (partition by lesson_id order by source_order)::integer as lesson_offset
  from new_seed
),
max_orders as (
  select lesson.id as lesson_id, coalesce(max(question.display_order), 0) as max_order
  from (select distinct lesson_id as id from ordered) lesson
  left join public.questions question on question.lesson_id = lesson.id
  group by lesson.id
)
  id, certification_id, domain_id, topic_id, lesson_id, question_text,
  question_type, difficulty, explanation, is_published, display_order
)
select ordered.id, ordered.certification_id, ordered.domain_id, ordered.topic_id,
  ordered.lesson_id, ordered.question_text, ordered.question_type, ordered.difficulty,
  ordered.explanation, ordered.is_published, max_orders.max_order + ordered.lesson_offset
from ordered join max_orders on max_orders.lesson_id = ordered.lesson_id
order by ordered.source_order
on conflict (id) do nothing;

select seed.id, seed.question_id, seed.option_text, seed.is_correct, seed.explanation, seed.display_order
from imported_question_option_batch3_seed seed
join public.questions question on question.id = seed.question_id
on conflict (id) do nothing;

do $$
declare question_count integer; option_count integer; lesson_count integer; invalid_groups integer;
begin
  select count(*), count(distinct lesson_id) into question_count, lesson_count
  from public.questions where id::text like '64000000-0000-4000-8000-%';
  select count(*) into option_count from public.question_options where id::text like '75000000-0000-4000-8000-%';
  select count(*) into invalid_groups from (
    select question.id from public.questions question
    join public.question_options option on option.question_id = question.id
    where question.id::text like '64000000-0000-4000-8000-%'
    group by question.id having count(*) <> 4 or count(*) filter (where option.is_correct) <> 1
  ) invalid;
  if question_count <> 25 or option_count <> 100 or lesson_count <> 5 or invalid_groups <> 0 then
    raise exception 'Validação falhou: questões %, alternativas %, lições %, grupos inválidos %.', question_count, option_count, lesson_count, invalid_groups;
  end if;
end
$$;

commit;
