insert into imported_question_batch3_seed values
  ('64000000-0000-4000-8000-000000000001', 'az-900', 'software-as-a-service', 'single_choice', 'O que caracteriza o modelo Software as a Service (SaaS)?', 'easy', 'Software as a Service (SaaS) e um modelo de servico de nuvem em que o provedor entrega uma aplicacao completa e pronta para uso pela internet, gerenciando toda a infraestrutura, a plataforma e o proprio software, restando ao cliente apenas utilizar a aplicacao e gerenciar seus dados e usuarios.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 1),
  ('64000000-0000-4000-8000-000000000002', 'az-900', 'software-as-a-service', 'single_choice', 'Qual das opcoes a seguir e um exemplo tipico de aplicacao SaaS?', 'easy', 'Um exemplo tipico de aplicacao SaaS e um servico de e-mail corporativo baseado na nuvem, acessado diretamente pelo navegador ou por um aplicativo cliente, sem que o usuario precise instalar, configurar ou manter qualquer parte da infraestrutura ou do software subjacente.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 2),
  ('64000000-0000-4000-8000-000000000003', 'az-900', 'software-as-a-service', 'single_choice', 'Uma pequena empresa deseja adotar uma ferramenta de gestao de relacionamento com clientes (CRM) o mais rapido possivel, sem contratar uma equipe de TI para instalar, configurar ou manter servidores e software. Qual modelo de servico de nuvem melhor atende a essa necessidade?', 'medium', 'Para uma empresa que deseja adotar rapidamente uma ferramenta de CRM sem contratar uma equipe de TI para gerenciar infraestrutura, o modelo SaaS e o mais adequado, pois entrega uma aplicacao completa e pronta para uso, com toda a infraestrutura, plataforma e manutencao do software geridas pelo provedor de nuvem.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 3),
  ('64000000-0000-4000-8000-000000000004', 'az-900', 'software-as-a-service', 'single_choice', 'Comparando o modelo SaaS com os modelos IaaS e PaaS quanto a responsabilidade do cliente sobre a manutencao do software da aplicacao em si, qual afirmacao esta correta?', 'medium', 'A responsabilidade pela manutencao do software da aplicacao varia conforme o modelo: em SaaS, o provedor mantem e atualiza toda a aplicacao; em IaaS, o cliente e responsavel pela aplicacao e pelo sistema operacional da maquina virtual; e em PaaS, o cliente mantem apenas o codigo de sua propria aplicacao, enquanto o provedor cuida do runtime e da infraestrutura subjacente.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 4),
  ('64000000-0000-4000-8000-000000000005', 'az-900', 'software-as-a-service', 'single_choice', 'Uma empresa de contabilidade esta decidindo entre adotar um software de gestao financeira no modelo SaaS ou desenvolver uma aplicacao propria hospedada em maquinas virtuais (IaaS), sabendo que a equipe de TI e pequena e que a empresa nao tem necessidade de customizacoes profundas no fluxo de trabalho padrao do software. Qual analise melhor orienta essa decisao?', 'hard', 'Considerando que a equipe de TI da empresa e pequena e que nao ha necessidade de customizacoes profundas no fluxo de trabalho, o modelo SaaS tende a ser a escolha mais adequada, pois permite adotar uma solucao de gestao financeira pronta, com toda a manutencao de infraestrutura, plataforma e aplicacao geridas pelo provedor, reduzindo significativamente a carga operacional sobre a equipe interna.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 5),
  ('64000000-0000-4000-8000-000000000006', 'az-900', 'choosing-iaas-paas-saas', 'single_choice', 'Qual fator e geralmente considerado ao decidir entre os modelos IaaS, PaaS e SaaS para um novo projeto?', 'easy', 'Ao decidir entre IaaS, PaaS e SaaS, um fator central e o nivel de controle desejado sobre a infraestrutura, o sistema operacional e a aplicacao, frente a carga de gerenciamento que a equipe esta disposta ou capacitada a assumir, ja que cada modelo desloca essa responsabilidade de forma diferente entre cliente e provedor.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 6),
  ('64000000-0000-4000-8000-000000000007', 'az-900', 'choosing-iaas-paas-saas', 'single_choice', 'Entre os tres modelos de servico de nuvem, qual deles exige, em geral, o maior nivel de gerenciamento por parte do cliente?', 'easy', 'Entre os tres modelos, o IaaS exige, em geral, o maior nivel de gerenciamento por parte do cliente, que fica responsavel por administrar o sistema operacional, o runtime e a aplicacao instalada sobre a infraestrutura fornecida pelo provedor, ao contrario de PaaS e SaaS, em que o provedor assume progressivamente mais camadas.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 7),
  ('64000000-0000-4000-8000-000000000008', 'az-900', 'choosing-iaas-paas-saas', 'single_choice', 'Uma equipe de desenvolvimento precisa migrar uma aplicacao legada que depende de uma versao especifica e pouco comum de sistema operacional, com configuracoes muito particulares que nao sao suportadas por ambientes de plataforma gerenciada. Qual modelo de servico de nuvem e mais adequado para essa migracao?', 'medium', 'Para uma aplicacao legada que depende de uma versao especifica e pouco comum de sistema operacional, o IaaS e o modelo mais adequado, pois oferece a flexibilidade e o controle necessarios para configurar uma maquina virtual exatamente com as caracteristicas exigidas pela aplicacao, algo que ambientes PaaS gerenciados geralmente nao permitem.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 8),
  ('64000000-0000-4000-8000-000000000009', 'az-900', 'choosing-iaas-paas-saas', 'single_choice', 'Uma equipe de desenvolvimento quer focar exclusivamente na logica de negocio de uma nova aplicacao web, sem se preocupar com a instalacao, configuracao ou atualizacao do sistema operacional e do runtime da linguagem de programacao utilizada. Qual modelo de servico de nuvem atende diretamente a essa necessidade?', 'medium', 'O PaaS atende diretamente a essa necessidade, pois oferece um ambiente de execucao gerenciado no qual o provedor cuida do sistema operacional, do runtime da linguagem de programacao e da infraestrutura subjacente, permitindo que a equipe de desenvolvimento foque exclusivamente na logica de negocio da aplicacao.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 9),
  ('64000000-0000-4000-8000-000000000010', 'az-900', 'choosing-iaas-paas-saas', 'single_choice', 'Uma organizacao esta planejando modernizar seu portfolio de aplicacoes: uma aplicacao de folha de pagamento sera substituida por um software de mercado pronto, uma nova aplicacao interna sera desenvolvida do zero pela equipe com foco apenas na logica de negocio, e um sistema legado critico, com dependencias muito especificas de hardware, permanecera como esta por enquanto. Qual combinacao de modelos de servico melhor reflete essa estrategia?', 'hard', 'A combinacao mais adequada e adotar SaaS para o software de folha de pagamento pronto, aproveitando uma solucao ja gerenciada pelo provedor; utilizar PaaS para a nova aplicacao interna desenvolvida pela equipe, permitindo foco na logica de negocio; e manter o sistema legado critico, com dependencias especificas de hardware, em uma abordagem mais proxima de IaaS ou on-premises, que oferece o controle necessario para essas particularidades.', true, 'Microsoft Learn - Modulo ''Describe cloud service types'' (Percurso: Describe cloud concepts, AZ-900)', 10),
  ('64000000-0000-4000-8000-000000000011', 'az-900', 'azure-regions', 'single_choice', 'O que e uma regiao do Azure?', 'easy', 'Uma regiao do Azure e um conjunto de datacenters implantados dentro de um perimetro de latencia definido e conectados por uma rede dedicada de alta velocidade, permitindo que os clientes escolham onde hospedar seus recursos, geralmente proximos a seus usuarios finais.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 11),
  ('64000000-0000-4000-8000-000000000012', 'az-900', 'azure-regions', 'single_choice', 'Por que a escolha da regiao do Azure onde um recurso sera hospedado pode ser importante para uma aplicacao?', 'easy', 'A escolha da regiao do Azure pode ser importante porque influencia diretamente fatores como a latencia de acesso percebida pelos usuarios finais, a disponibilidade de determinados servicos, que podem variar entre regioes, e requisitos de conformidade regulatoria relacionados a residencia de dados em determinadas geografias.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 12),
  ('64000000-0000-4000-8000-000000000013', 'az-900', 'azure-regions', 'single_choice', 'Uma empresa de jogos online tem a maior parte de seus jogadores localizados na America do Sul e percebe reclamacoes frequentes sobre lentidao na aplicacao. Qual acao relacionada a escolha de regiao do Azure pode ajudar a reduzir essa lentidao percebida pelos jogadores?', 'medium', 'Migrar a aplicacao para uma regiao do Azure geograficamente mais proxima da America do Sul tende a reduzir a distancia fisica que os dados precisam percorrer entre os servidores e os jogadores, o que geralmente resulta em menor latencia e uma experiencia de uso mais fluida para o publico local.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 13),
  ('64000000-0000-4000-8000-000000000014', 'az-900', 'azure-regions', 'single_choice', 'Uma equipe de TI esta escolhendo entre duas regioes do Azure para hospedar uma nova aplicacao critica, e percebe que uma das regioes nao oferece suporte a um servico especifico de banco de dados gerenciado que a aplicacao precisa utilizar. Qual conclusao e mais adequada a partir dessa informacao?', 'medium', 'Como a disponibilidade de servicos especificos, como determinados bancos de dados gerenciados, pode variar entre regioes do Azure, e essencial que a equipe de TI verifique previamente se os servicos necessarios para a aplicacao estao disponiveis na regiao candidata antes de tomar a decisao final sobre onde hospedar a aplicacao critica.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 14),
  ('64000000-0000-4000-8000-000000000015', 'az-900', 'azure-regions', 'single_choice', 'Uma empresa multinacional precisa escolher a regiao do Azure para hospedar uma nova aplicacao voltada a clientes na Europa, considerando simultaneamente a latencia para os usuarios europeus, a disponibilidade de servicos especificos exigidos pela aplicacao e possiveis requisitos de residencia de dados impostos pela legislacao local. Qual abordagem e mais adequada para essa decisao?', 'hard', 'A abordagem mais adequada e avaliar de forma combinada a proximidade geografica da regiao com os usuarios europeus, visando reduzir a latencia, a disponibilidade dos servicos especificos exigidos pela aplicacao naquela regiao, e os requisitos de residencia de dados impostos pela legislacao local, escolhendo a regiao do Azure que melhor equilibre esses tres fatores simultaneamente.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 15),
  ('64000000-0000-4000-8000-000000000016', 'az-900', 'region-pairs-and-sovereign-regions', 'single_choice', 'O que e um par de regioes (region pair) no Azure?', 'easy', 'Um par de regioes (region pair) no Azure e a associacao entre duas regioes especificas, geralmente localizadas dentro da mesma geografia, definida previamente pela Microsoft, frequentemente utilizada em estrategias de replicacao de dados e recuperacao de desastres entre regioes.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 16),
  ('64000000-0000-4000-8000-000000000017', 'az-900', 'region-pairs-and-sovereign-regions', 'single_choice', 'O que caracteriza uma regiao soberana (sovereign region) no Azure?', 'easy', 'Uma regiao soberana (sovereign region) no Azure e uma instancia fisica e logicamente isolada das demais regioes publicas do Azure, frequentemente criada para atender a requisitos legais, regulatorios ou de seguranca especificos de um governo ou setor, como e o caso de instancias voltadas a determinados orgaos governamentais.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 17),
  ('64000000-0000-4000-8000-000000000018', 'az-900', 'region-pairs-and-sovereign-regions', 'single_choice', 'Uma empresa deseja implementar uma estrategia de recuperacao de desastres para sua aplicacao critica, replicando dados entre duas regioes do Azure que ja possuem uma relacao definida previamente pela Microsoft para esse tipo de cenario. Qual conceito do Azure a empresa deve considerar ao planejar essa replicacao?', 'medium', 'O conceito de pares de regioes (region pairs) e o mais relevante para esse cenario, ja que a Microsoft define previamente associacoes entre duas regioes, geralmente dentro da mesma geografia, o que facilita e orienta estrategias de replicacao de dados e recuperacao de desastres entre elas.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 18),
  ('64000000-0000-4000-8000-000000000019', 'az-900', 'region-pairs-and-sovereign-regions', 'single_choice', 'Uma agencia de um governo nacional precisa hospedar sistemas que armazenam dados extremamente sensiveis de cidadaos, sujeitos a exigencias rigidas de isolamento e conformidade regulatoria especificas do setor publico daquele pais. Qual tipo de oferta do Azure e mais relevante para essa agencia avaliar?', 'medium', 'Para uma agencia governamental que precisa hospedar dados extremamente sensiveis sujeitos a exigencias rigidas de isolamento e conformidade regulatoria, uma regiao soberana do Azure e a oferta mais relevante a ser avaliada, ja que esse tipo de instancia e projetado especificamente para atender requisitos legais e regulatorios especificos de determinados governos ou setores.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 19),
  ('64000000-0000-4000-8000-000000000020', 'az-900', 'region-pairs-and-sovereign-regions', 'single_choice', 'Uma equipe de arquitetura esta avaliando duas necessidades distintas para uma organizacao internacional: primeiro, garantir recuperacao de desastres para uma aplicacao comercial hospedada em regioes publicas comuns do Azure; segundo, hospedar um sistema governamental com exigencias regulatorias extremamente rigidas de isolamento. Qual analise melhor diferencia os conceitos de pares de regioes e regioes soberanas para atender a essas duas necessidades?', 'hard', 'Pares de regioes sao mais adequados para a estrategia de recuperacao de desastres da aplicacao comercial, ja que associam previamente duas regioes publicas do Azure para fins de replicacao de dados, enquanto regioes soberanas sao mais adequadas para o sistema governamental com exigencias regulatorias rigidas, por oferecerem um ambiente isolado e voltado especificamente a requisitos de conformidade de determinados governos ou setores.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 20),
  ('64000000-0000-4000-8000-000000000021', 'az-900', 'resources-and-resource-groups', 'single_choice', 'O que e um recurso (resource) no Azure?', 'easy', 'Um recurso (resource) no Azure e uma entidade gerenciavel individual disponibilizada pela plataforma, como uma maquina virtual, um banco de dados, uma conta de armazenamento ou uma rede virtual, sendo a unidade basica que os clientes criam, configuram e utilizam dentro de uma assinatura do Azure.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 21),
  ('64000000-0000-4000-8000-000000000022', 'az-900', 'resources-and-resource-groups', 'single_choice', 'O que e um grupo de recursos (resource group) no Azure?', 'easy', 'Um grupo de recursos (resource group) no Azure e um conteiner logico utilizado para agrupar e gerenciar recursos relacionados, como maquinas virtuais, bancos de dados e redes virtuais de um mesmo projeto ou solucao, facilitando o gerenciamento, a aplicacao de politicas e o controle de custos de forma conjunta.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 22),
  ('64000000-0000-4000-8000-000000000023', 'az-900', 'resources-and-resource-groups', 'single_choice', 'Uma equipe de desenvolvimento esta organizando os recursos do Azure de tres projetos distintos dentro da mesma assinatura, e deseja poder gerenciar, monitorar e aplicar politicas de forma independente para os recursos de cada projeto. Qual pratica, utilizando grupos de recursos, atende a essa necessidade?', 'medium', 'Criar um grupo de recursos separado para cada um dos tres projetos, agrupando dentro de cada grupo apenas os recursos relacionados aquele projeto especifico, permite que a equipe gerencie, monitore e aplique politicas de forma independente para os recursos de cada projeto, mesmo compartilhando a mesma assinatura do Azure.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 23),
  ('64000000-0000-4000-8000-000000000024', 'az-900', 'resources-and-resource-groups', 'single_choice', 'Uma equipe exclui, por engano, um grupo de recursos inteiro que continha uma maquina virtual, um banco de dados e uma conta de armazenamento utilizados por uma aplicacao em producao. Qual e a consequencia mais provavel dessa acao?', 'medium', 'Ao excluir um grupo de recursos, todos os recursos contidos nele, como a maquina virtual, o banco de dados e a conta de armazenamento do exemplo, sao geralmente excluidos juntamente com o proprio grupo, o que reforca a importancia de organizar cuidadosamente os recursos em grupos e de ter cautela antes de realizar essa acao em ambientes de producao.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 24),
  ('64000000-0000-4000-8000-000000000025', 'az-900', 'resources-and-resource-groups', 'single_choice', 'Uma empresa organiza seus recursos do Azure em grupos de recursos separados por ambiente (desenvolvimento, teste e producao), mas percebe que alguns recursos de teste dependem de recursos que estao no grupo de producao, criando uma dependencia entre grupos que dificulta a exclusao segura do ambiente de teste quando ele nao for mais necessario. Qual pratica melhor evita esse tipo de problema no futuro?', 'hard', 'A pratica mais adequada e planejar cuidadosamente as dependencias entre recursos no momento de organizar os grupos de recursos, evitando que recursos de um ambiente, como teste, dependam diretamente de recursos localizados em outro grupo, como producao, o que permite que cada grupo de recursos possa ser gerenciado, e eventualmente excluido, de forma mais segura e independente.', true, 'Microsoft Learn - Modulo ''Describe the core architectural components of Azure'' (Percurso: Describe core Azure services, AZ-900)', 25);
insert into imported_question_option_batch3_seed values
  ('75000000-0000-4000-8000-000000000001', '64000000-0000-4000-8000-000000000001', 'O provedor entrega uma aplicacao completa e pronta para uso pela internet, gerenciando toda a infraestrutura, plataforma e o proprio software.', true, 'Correta. Em SaaS, o provedor gerencia toda a pilha, incluindo infraestrutura, plataforma e a aplicacao, entregando um software pronto para uso pela internet.', 1),
  ('75000000-0000-4000-8000-000000000002', '64000000-0000-4000-8000-000000000001', 'O cliente precisa instalar e configurar manualmente o sistema operacional em cada maquina que acessara a aplicacao.', false, 'Incorreta. Instalar e configurar sistema operacional manualmente e caracteristico de ambientes on-premises ou IaaS, nao de SaaS.', 2),
  ('75000000-0000-4000-8000-000000000003', '64000000-0000-4000-8000-000000000001', 'O cliente e responsavel por desenvolver o codigo da aplicacao e o provedor apenas hospeda o hardware.', false, 'Incorreta. Em SaaS, o proprio software ja e fornecido pronto pelo provedor; o cliente nao precisa desenvolver a aplicacao.', 3),
  ('75000000-0000-4000-8000-000000000004', '64000000-0000-4000-8000-000000000001', 'O provedor fornece apenas o hardware fisico, deixando todo o restante da pilha sob responsabilidade do cliente.', false, 'Incorreta. Fornecer apenas o hardware fisico e mais proximo do modelo IaaS, e nao do SaaS.', 4),
  ('75000000-0000-4000-8000-000000000005', '64000000-0000-4000-8000-000000000002', 'Um servico de e-mail corporativo baseado na nuvem, acessado diretamente pelo navegador, sem necessidade de instalacao local do software.', true, 'Correta. Um servico de e-mail corporativo baseado na nuvem, acessado pelo navegador e totalmente gerenciado pelo provedor, e um exemplo classico de aplicacao SaaS.', 1),
  ('75000000-0000-4000-8000-000000000006', '64000000-0000-4000-8000-000000000002', 'Uma maquina virtual criada pelo cliente, na qual ele instala manualmente o sistema operacional e os aplicativos desejados.', false, 'Incorreta. Uma maquina virtual configurada manualmente pelo cliente e um exemplo de IaaS, e nao de SaaS.', 2),
  ('75000000-0000-4000-8000-000000000007', '64000000-0000-4000-8000-000000000002', 'Um ambiente de execucao de codigo em que o cliente publica sua propria aplicacao, mas o provedor gerencia o runtime.', false, 'Incorreta. Um ambiente de execucao de codigo gerenciado, no qual o cliente publica sua propria aplicacao, e caracteristico de PaaS.', 3),
  ('75000000-0000-4000-8000-000000000008', '64000000-0000-4000-8000-000000000002', 'Um servidor fisico alugado exclusivamente para o cliente, sem qualquer virtualizacao envolvida.', false, 'Incorreta. Um servidor fisico dedicado, sem virtualizacao, nao se enquadra no modelo SaaS.', 4),
  ('75000000-0000-4000-8000-000000000009', '64000000-0000-4000-8000-000000000003', 'IaaS, pois permite que a empresa configure suas proprias maquinas virtuais para hospedar o CRM.', false, 'Incorreta. IaaS ainda exige que a empresa gerencie o sistema operacional e a instalacao do software de CRM, o que contraria a necessidade de simplicidade descrita.', 1),
  ('75000000-0000-4000-8000-000000000010', '64000000-0000-4000-8000-000000000003', 'PaaS, pois permite que a empresa desenvolva sua propria aplicacao de CRM utilizando um ambiente de execucao gerenciado.', false, 'Incorreta. PaaS ainda exigiria que a empresa desenvolvesse ou adaptasse uma aplicacao, o que nao atende a necessidade de uma solucao pronta e rapida.', 2),
  ('75000000-0000-4000-8000-000000000011', '64000000-0000-4000-8000-000000000003', 'SaaS, pois oferece uma aplicacao de CRM completa e pronta para uso, com toda a infraestrutura e manutencao gerenciadas pelo provedor.', true, 'Correta. O SaaS oferece uma aplicacao de CRM pronta para uso, sem exigir que a empresa gerencie infraestrutura, plataforma ou manutencao do software.', 3),
  ('75000000-0000-4000-8000-000000000012', '64000000-0000-4000-8000-000000000003', 'Um servidor fisico proprio, instalado no escritorio da empresa, com o software de CRM instalado localmente.', false, 'Incorreta. Um servidor fisico proprio exigiria investimento em hardware e manutencao continua pela equipe de TI, o que contraria a necessidade descrita.', 4),
  ('75000000-0000-4000-8000-000000000013', '64000000-0000-4000-8000-000000000004', 'Em SaaS, o cliente e sempre responsavel por aplicar atualizacoes e correcoes diretamente no codigo da aplicacao utilizada.', false, 'Incorreta. Em SaaS, e o provedor, e nao o cliente, que e responsavel por manter e atualizar o codigo da aplicacao fornecida.', 1),
  ('75000000-0000-4000-8000-000000000014', '64000000-0000-4000-8000-000000000004', 'Em IaaS, PaaS e SaaS, a responsabilidade pela manutencao do software da aplicacao e sempre identica, sem qualquer diferenca entre os modelos.', false, 'Incorreta. A responsabilidade pela manutencao do software da aplicacao varia significativamente entre os tres modelos, nao sendo identica.', 2),
  ('75000000-0000-4000-8000-000000000015', '64000000-0000-4000-8000-000000000004', 'Em IaaS, o cliente tem menos responsabilidade sobre a aplicacao do que em SaaS, ja que o provedor cuida de tudo em IaaS.', false, 'Incorreta. E o oposto: em IaaS o cliente tem mais responsabilidade sobre a aplicacao e o sistema operacional do que em SaaS.', 3),
  ('75000000-0000-4000-8000-000000000016', '64000000-0000-4000-8000-000000000004', 'Em SaaS, o provedor e responsavel por manter e atualizar o software da aplicacao, enquanto em IaaS essa responsabilidade e do cliente, e em PaaS o cliente mantem apenas o codigo da propria aplicacao.', true, 'Correta. Em SaaS o provedor mantem a aplicacao, em IaaS o cliente e responsavel pela aplicacao e pelo sistema operacional, e em PaaS o cliente mantem apenas o codigo de sua propria aplicacao.', 4),
  ('75000000-0000-4000-8000-000000000017', '64000000-0000-4000-8000-000000000005', 'A empresa deve sempre escolher IaaS, independentemente do tamanho da equipe de TI ou da necessidade de customizacao, por oferecer mais controle tecnico.', false, 'Incorreta. Escolher sempre IaaS, ignorando o tamanho da equipe de TI e a real necessidade de customizacao, pode gerar sobrecarga operacional desnecessaria para essa empresa.', 1),
  ('75000000-0000-4000-8000-000000000018', '64000000-0000-4000-8000-000000000005', 'Dado que a equipe de TI e pequena e nao ha necessidade de customizacoes profundas, o SaaS tende a ser mais adequado, pois reduz a carga operacional de manutencao e permite que a empresa utilize uma solucao pronta e gerenciada pelo provedor.', true, 'Correta. Com equipe de TI pequena e baixa necessidade de customizacao, o SaaS reduz a carga operacional, sendo geralmente a opcao mais adequada nesse cenario.', 2),
  ('75000000-0000-4000-8000-000000000019', '64000000-0000-4000-8000-000000000005', 'A escolha entre SaaS e IaaS nunca deve considerar o tamanho da equipe de TI disponivel na empresa, sendo esse um fator irrelevante.', false, 'Incorreta. O tamanho da equipe de TI disponivel e um fator relevante nessa decisao, especialmente quando a equipe e pequena e a manutencao de infraestrutura seria uma carga adicional significativa.', 3),
  ('75000000-0000-4000-8000-000000000020', '64000000-0000-4000-8000-000000000005', 'A empresa deve obrigatoriamente desenvolver sua propria aplicacao do zero, independentemente do modelo de nuvem escolhido, para garantir qualidade.', false, 'Incorreta. Desenvolver uma aplicacao do zero nao e uma exigencia obrigatoria e seria desproporcional para uma necessidade que um software pronto de mercado ja pode atender.', 4),
  ('75000000-0000-4000-8000-000000000021', '64000000-0000-4000-8000-000000000006', 'O nivel de controle desejado sobre a infraestrutura frente a carga de gerenciamento que a equipe esta disposta a assumir.', true, 'Correta. O nivel de controle desejado sobre a infraestrutura, em contraste com a carga de gerenciamento que a equipe pode assumir, e um fator central nessa decisao.', 1),
  ('75000000-0000-4000-8000-000000000022', '64000000-0000-4000-8000-000000000006', 'Exclusivamente a cor da interface grafica oferecida por cada um dos tres modelos de servico.', false, 'Incorreta. A cor da interface grafica e um detalhe irrelevante para a escolha tecnica entre IaaS, PaaS e SaaS.', 2),
  ('75000000-0000-4000-8000-000000000023', '64000000-0000-4000-8000-000000000006', 'O numero de feriados nacionais previstos no calendario da equipe responsavel pelo projeto.', false, 'Incorreta. O numero de feriados nacionais nao e um criterio tecnico relevante para essa decisao de arquitetura.', 3),
  ('75000000-0000-4000-8000-000000000024', '64000000-0000-4000-8000-000000000006', 'A quantidade de cadeiras disponiveis no escritorio onde a equipe de desenvolvimento trabalha.', false, 'Incorreta. A quantidade de cadeiras no escritorio nao tem qualquer relacao com a escolha entre modelos de servico de nuvem.', 4),
  ('75000000-0000-4000-8000-000000000025', '64000000-0000-4000-8000-000000000007', 'IaaS, pois o cliente e responsavel por gerenciar o sistema operacional, o runtime e a aplicacao instalada sobre a infraestrutura fornecida.', true, 'Correta. Em IaaS, o cliente assume mais responsabilidades de gerenciamento, incluindo sistema operacional, runtime e aplicacao, em comparacao a PaaS e SaaS.', 1),
  ('75000000-0000-4000-8000-000000000026', '64000000-0000-4000-8000-000000000007', 'PaaS, pois o cliente precisa gerenciar tanto o sistema operacional quanto o hardware fisico do datacenter.', false, 'Incorreta. Em PaaS, o provedor gerencia o sistema operacional e o hardware fisico; o cliente foca principalmente no codigo da aplicacao.', 2),
  ('75000000-0000-4000-8000-000000000027', '64000000-0000-4000-8000-000000000007', 'SaaS, pois o cliente e responsavel por toda a infraestrutura, plataforma e manutencao da aplicacao utilizada.', false, 'Incorreta. Em SaaS, e o provedor quem gerencia toda a infraestrutura, plataforma e a propria aplicacao, e nao o cliente.', 3),
  ('75000000-0000-4000-8000-000000000028', '64000000-0000-4000-8000-000000000007', 'Nenhum dos tres modelos exige qualquer nivel de gerenciamento por parte do cliente, em qualquer cenario.', false, 'Incorreta. Mesmo no modelo com menor carga de gerenciamento (SaaS), o cliente ainda mantem alguma responsabilidade, como a gestao de dados e usuarios.', 4),
  ('75000000-0000-4000-8000-000000000029', '64000000-0000-4000-8000-000000000008', 'SaaS, pois permite executar qualquer aplicacao legada sem qualquer restricao de sistema operacional ou configuracao.', false, 'Incorreta. SaaS oferece aplicacoes prontas do provedor, sem permitir a instalacao de uma aplicacao legada com configuracoes de sistema operacional muito especificas.', 1),
  ('75000000-0000-4000-8000-000000000030', '64000000-0000-4000-8000-000000000008', 'PaaS, pois oferece um ambiente de execucao flexivel o suficiente para qualquer versao de sistema operacional exigida pela aplicacao legada.', false, 'Incorreta. Ambientes PaaS geralmente suportam um conjunto definido de runtimes e versoes, podendo nao acomodar configuracoes de sistema operacional muito especificas e incomuns.', 2),
  ('75000000-0000-4000-8000-000000000031', '64000000-0000-4000-8000-000000000008', 'IaaS, pois permite que a equipe configure uma maquina virtual com a versao especifica do sistema operacional exigida pela aplicacao legada.', true, 'Correta. O IaaS oferece o nivel de controle necessario para configurar uma maquina virtual com a versao especifica de sistema operacional exigida pela aplicacao legada.', 3),
  ('75000000-0000-4000-8000-000000000032', '64000000-0000-4000-8000-000000000008', 'Nenhum modelo de nuvem seria capaz de hospedar uma aplicacao legada com configuracoes muito especificas de sistema operacional.', false, 'Incorreta. O IaaS e capaz de hospedar aplicacoes legadas com configuracoes especificas, ja que oferece controle direto sobre o sistema operacional da maquina virtual.', 4),
  ('75000000-0000-4000-8000-000000000033', '64000000-0000-4000-8000-000000000009', 'IaaS, pois permite que a equipe instale e configure manualmente o runtime da linguagem de programacao na maquina virtual.', false, 'Incorreta. Em IaaS, a propria equipe precisaria instalar e configurar o runtime, o que contraria o desejo de nao se preocupar com essas tarefas.', 1),
  ('75000000-0000-4000-8000-000000000034', '64000000-0000-4000-8000-000000000009', 'PaaS, pois oferece um ambiente de execucao gerenciado, no qual o provedor cuida do sistema operacional e do runtime, permitindo que a equipe foque no codigo da aplicacao.', true, 'Correta. O PaaS oferece um ambiente gerenciado de sistema operacional e runtime, permitindo que a equipe foque exclusivamente na logica de negocio da aplicacao.', 2),
  ('75000000-0000-4000-8000-000000000035', '64000000-0000-4000-8000-000000000009', 'SaaS, pois fornece uma aplicacao pronta, eliminando totalmente a necessidade de a equipe escrever qualquer codigo.', false, 'Incorreta. Em SaaS, nao ha desenvolvimento de codigo por parte da equipe, o que nao atende ao cenario de uma equipe que deseja desenvolver sua propria logica de negocio.', 3),
  ('75000000-0000-4000-8000-000000000036', '64000000-0000-4000-8000-000000000009', 'Um servidor fisico proprio, instalado no datacenter da empresa, gerenciado inteiramente pela equipe de desenvolvimento.', false, 'Incorreta. Um servidor fisico proprio exigiria que a propria equipe gerenciasse todo o sistema operacional e o runtime, o que contraria a necessidade descrita.', 4),
  ('75000000-0000-4000-8000-000000000037', '64000000-0000-4000-8000-000000000010', 'Utilizar exclusivamente IaaS para todas as tres iniciativas, independentemente das diferentes necessidades de cada uma.', false, 'Incorreta. Utilizar exclusivamente IaaS para todas as iniciativas ignora as diferentes necessidades de controle e gerenciamento de cada uma, especialmente da aplicacao de mercado pronta.', 1),
  ('75000000-0000-4000-8000-000000000038', '64000000-0000-4000-8000-000000000010', 'Adotar SaaS para o software de folha de pagamento pronto, PaaS para a nova aplicacao desenvolvida internamente, e manter o sistema legado critico em uma abordagem mais proxima de IaaS ou on-premises, devido as suas dependencias especificas.', true, 'Correta. Essa combinacao reflete adequadamente as diferentes necessidades: SaaS para o software pronto, PaaS para a nova aplicacao focada em logica de negocio, e uma abordagem mais controlada para o sistema legado com dependencias especificas.', 2),
  ('75000000-0000-4000-8000-000000000039', '64000000-0000-4000-8000-000000000010', 'Utilizar exclusivamente SaaS para todas as tres iniciativas, incluindo o desenvolvimento da nova aplicacao interna e o sistema legado critico.', false, 'Incorreta. SaaS nao seria adequado para o desenvolvimento de uma nova aplicacao interna nem para um sistema legado com dependencias especificas de hardware, ja que nao permite esse tipo de controle ou desenvolvimento personalizado.', 3),
  ('75000000-0000-4000-8000-000000000040', '64000000-0000-4000-8000-000000000010', 'Utilizar exclusivamente PaaS para todas as tres iniciativas, incluindo a adocao do software de folha de pagamento pronto.', false, 'Incorreta. Para um software de mercado ja pronto, como a solucao de folha de pagamento, o modelo SaaS e mais adequado do que o PaaS, que e voltado ao desenvolvimento de aplicacoes proprias.', 4),
  ('75000000-0000-4000-8000-000000000041', '64000000-0000-4000-8000-000000000011', 'Um conjunto de datacenters implantados dentro de um perimetro de latencia definido e conectados por uma rede dedicada de alta velocidade.', true, 'Correta. Uma regiao do Azure e composta por um conjunto de datacenters implantados dentro de um perimetro de latencia definido, conectados por uma rede dedicada.', 1),
  ('75000000-0000-4000-8000-000000000042', '64000000-0000-4000-8000-000000000011', 'Um unico servidor fisico isolado, sem qualquer conexao com outros datacenters do Azure.', false, 'Incorreta. Uma regiao nao e um unico servidor isolado; ela e composta por multiplos datacenters interconectados.', 2),
  ('75000000-0000-4000-8000-000000000043', '64000000-0000-4000-8000-000000000011', 'Uma ferramenta de linha de comando utilizada exclusivamente para criar maquinas virtuais no Azure.', false, 'Incorreta. Uma regiao nao e uma ferramenta de linha de comando; e um conceito de infraestrutura geografica do Azure.', 3),
  ('75000000-0000-4000-8000-000000000044', '64000000-0000-4000-8000-000000000011', 'Um grupo de contas de usuario administrativas criadas para gerenciar uma assinatura especifica.', false, 'Incorreta. Uma regiao nao esta relacionada a contas de usuario administrativas; e um conceito de infraestrutura fisica.', 4),
  ('75000000-0000-4000-8000-000000000045', '64000000-0000-4000-8000-000000000012', 'Porque a regiao escolhida pode influenciar fatores como latencia de acesso, disponibilidade de determinados servicos e requisitos de conformidade.', true, 'Correta. A regiao escolhida pode influenciar diretamente a latencia percebida pelos usuarios, a disponibilidade de certos servicos e requisitos legais de conformidade.', 1),
  ('75000000-0000-4000-8000-000000000046', '64000000-0000-4000-8000-000000000012', 'Porque a escolha da regiao determina exclusivamente a cor do tema visual exibido no portal do Azure.', false, 'Incorreta. A cor do tema visual do portal e uma preferencia pessoal do usuario, sem qualquer relacao com a regiao escolhida para hospedar recursos.', 2),
  ('75000000-0000-4000-8000-000000000047', '64000000-0000-4000-8000-000000000012', 'Porque a escolha da regiao altera automaticamente o idioma padrao de todos os aplicativos hospedados no Azure.', false, 'Incorreta. O idioma dos aplicativos hospedados e definido pelo proprio desenvolvimento da aplicacao, e nao pela regiao escolhida no Azure.', 3),
  ('75000000-0000-4000-8000-000000000048', '64000000-0000-4000-8000-000000000012', 'Porque a escolha da regiao determina o numero de funcionarios que a empresa cliente pode contratar.', false, 'Incorreta. O numero de funcionarios contratados pela empresa cliente nao tem qualquer relacao com a regiao do Azure escolhida para hospedar recursos.', 4),
  ('75000000-0000-4000-8000-000000000049', '64000000-0000-4000-8000-000000000013', 'Migrar a aplicacao para uma regiao do Azure geograficamente mais proxima da America do Sul, reduzindo a distancia fisica entre os servidores e os jogadores.', true, 'Correta. Migrar a aplicacao para uma regiao mais proxima geograficamente dos jogadores tende a reduzir a latencia percebida, melhorando a experiencia de uso.', 1),
  ('75000000-0000-4000-8000-000000000050', '64000000-0000-4000-8000-000000000013', 'Trocar o nome de exibicao da assinatura do Azure utilizada pela empresa para um nome em portugues.', false, 'Incorreta. Trocar o nome de exibicao da assinatura e uma alteracao puramente administrativa, sem qualquer impacto na latencia percebida pelos jogadores.', 2),
  ('75000000-0000-4000-8000-000000000051', '64000000-0000-4000-8000-000000000013', 'Aumentar o numero de administradores cadastrados na assinatura do Azure utilizada pela empresa.', false, 'Incorreta. Aumentar o numero de administradores cadastrados nao tem relacao com a latencia percebida pelos usuarios finais da aplicacao.', 3),
  ('75000000-0000-4000-8000-000000000052', '64000000-0000-4000-8000-000000000013', 'Reduzir o numero de jogadores que podem acessar o jogo simultaneamente, limitando o total de contas ativas.', false, 'Incorreta. Reduzir o numero de jogadores nao resolve o problema de latencia; apenas restringe artificialmente o acesso ao jogo.', 4),
  ('75000000-0000-4000-8000-000000000053', '64000000-0000-4000-8000-000000000014', 'Todos os servicos do Azure estao sempre disponiveis em todas as regioes, portanto essa informacao deve estar incorreta.', false, 'Incorreta. Nem todos os servicos do Azure estao disponiveis em todas as regioes; a disponibilidade de servicos pode variar entre diferentes regioes.', 1),
  ('75000000-0000-4000-8000-000000000054', '64000000-0000-4000-8000-000000000014', 'A disponibilidade de servicos especificos pode variar entre regioes do Azure, portanto a equipe deve verificar essa disponibilidade antes de escolher a regiao final para hospedar a aplicacao.', true, 'Correta. A disponibilidade de servicos pode variar entre regioes, tornando essencial verificar se os servicos necessarios estao disponiveis antes de escolher a regiao final.', 2),
  ('75000000-0000-4000-8000-000000000055', '64000000-0000-4000-8000-000000000014', 'A equipe deve ignorar completamente essa limitacao, ja que a escolha da regiao nunca afeta quais servicos podem ser utilizados.', false, 'Incorreta. A escolha da regiao pode, sim, afetar quais servicos estao disponiveis, tornando essa limitacao relevante para a decisao da equipe.', 3),
  ('75000000-0000-4000-8000-000000000056', '64000000-0000-4000-8000-000000000014', 'A unica solucao possivel e desenvolver o proprio banco de dados gerenciado do zero, sem utilizar nenhum servico do Azure.', false, 'Incorreta. Desenvolver um banco de dados gerenciado do zero e desproporcional; a equipe pode simplesmente escolher outra regiao que ofereça o servico necessario.', 4),
  ('75000000-0000-4000-8000-000000000057', '64000000-0000-4000-8000-000000000015', 'Escolher a regiao mais barata disponivel no mundo todo, independentemente de sua localizacao geografica ou dos demais fatores envolvidos.', false, 'Incorreta. Escolher exclusivamente pelo menor custo, ignorando latencia, disponibilidade de servicos e requisitos legais, pode comprometer o desempenho e a conformidade da aplicacao.', 1),
  ('75000000-0000-4000-8000-000000000058', '64000000-0000-4000-8000-000000000015', 'Avaliar de forma combinada a proximidade geografica com os usuarios europeus, a disponibilidade dos servicos especificos exigidos pela aplicacao naquela regiao e os requisitos de residencia de dados aplicaveis, escolhendo a regiao que melhor equilibre esses fatores.', true, 'Correta. A decisao deve considerar de forma combinada latencia, disponibilidade de servicos e requisitos legais de residencia de dados, escolhendo a regiao que melhor equilibre esses fatores.', 2),
  ('75000000-0000-4000-8000-000000000059', '64000000-0000-4000-8000-000000000015', 'Escolher aleatoriamente qualquer regiao disponivel no Azure, ja que todos os fatores mencionados sao igualmente irrelevantes para essa decisao.', false, 'Incorreta. Latencia, disponibilidade de servicos e requisitos de residencia de dados sao fatores relevantes, e nao irrelevantes, para essa decisao de arquitetura.', 3),
  ('75000000-0000-4000-8000-000000000060', '64000000-0000-4000-8000-000000000015', 'Ignorar completamente os requisitos de residencia de dados, priorizando exclusivamente a regiao com menor latencia possivel para os usuarios.', false, 'Incorreta. Ignorar requisitos legais de residencia de dados pode gerar problemas de conformidade significativos para a empresa, mesmo que a latencia seja otimizada.', 4),
  ('75000000-0000-4000-8000-000000000061', '64000000-0000-4000-8000-000000000016', 'Duas regioes especificas, geralmente dentro da mesma geografia, associadas previamente pela Microsoft, frequentemente utilizadas para replicacao de dados e recuperacao de desastres.', true, 'Correta. Um par de regioes e a associacao entre duas regioes, definida previamente pela Microsoft, geralmente dentro da mesma geografia, utilizada para estrategias de replicacao e recuperacao de desastres.', 1),
  ('75000000-0000-4000-8000-000000000062', '64000000-0000-4000-8000-000000000016', 'Duas contas de usuario administrativas criadas para gerenciar a mesma assinatura do Azure de forma redundante.', false, 'Incorreta. Um par de regioes nao esta relacionado a contas de usuario administrativas; e um conceito de infraestrutura geografica.', 2),
  ('75000000-0000-4000-8000-000000000063', '64000000-0000-4000-8000-000000000016', 'Duas maquinas virtuais localizadas na mesma zona de disponibilidade dentro de uma unica regiao do Azure.', false, 'Incorreta. Um par de regioes refere-se a duas regioes geograficas distintas, e nao a duas maquinas virtuais na mesma zona de disponibilidade.', 3),
  ('75000000-0000-4000-8000-000000000064', '64000000-0000-4000-8000-000000000016', 'Um conjunto de politicas de seguranca aplicadas exclusivamente a recursos de uma unica regiao especifica.', false, 'Incorreta. Um par de regioes nao e um conjunto de politicas de seguranca; e uma associacao geografica entre duas regioes distintas.', 4),
  ('75000000-0000-4000-8000-000000000065', '64000000-0000-4000-8000-000000000017', 'Uma instancia do Azure fisica e logicamente isolada das demais regioes publicas, frequentemente atendendo a requisitos legais ou regulatorios especificos de um governo ou setor.', true, 'Correta. Uma regiao soberana e uma instancia do Azure isolada, geralmente criada para atender requisitos legais ou regulatorios especificos de um governo ou setor.', 1),
  ('75000000-0000-4000-8000-000000000066', '64000000-0000-4000-8000-000000000017', 'Uma regiao do Azure que oferece precos mais baixos do que qualquer outra regiao disponivel globalmente.', false, 'Incorreta. Precos mais baixos nao sao a caracteristica que define uma regiao soberana; o foco esta no isolamento e na conformidade regulatoria.', 2),
  ('75000000-0000-4000-8000-000000000067', '64000000-0000-4000-8000-000000000017', 'Uma regiao exclusiva para hospedar aplicacoes de jogos eletronicos, sem qualquer outro tipo de uso permitido.', false, 'Incorreta. Regioes soberanas nao sao restritas a aplicacoes de jogos eletronicos; elas atendem a requisitos legais ou regulatorios mais amplos.', 3),
  ('75000000-0000-4000-8000-000000000068', '64000000-0000-4000-8000-000000000017', 'Uma regiao que permite apenas o uso de maquinas virtuais, sem suporte a qualquer outro tipo de servico do Azure.', false, 'Incorreta. Regioes soberanas nao se limitam apenas a maquinas virtuais; elas podem oferecer diversos servicos do Azure, conforme a instancia especifica.', 4),
  ('75000000-0000-4000-8000-000000000069', '64000000-0000-4000-8000-000000000018', 'O uso de pares de regioes (region pairs), que oferecem uma associacao pre-definida entre duas regioes, geralmente dentro da mesma geografia, adequada para estrategias de replicacao e recuperacao de desastres.', true, 'Correta. Pares de regioes oferecem uma associacao pre-definida entre duas regioes, sendo o conceito mais relevante para estrategias de replicacao e recuperacao de desastres.', 1),
  ('75000000-0000-4000-8000-000000000070', '64000000-0000-4000-8000-000000000018', 'O uso exclusivo de uma unica zona de disponibilidade dentro de uma unica regiao, sem qualquer replicacao entre regioes distintas.', false, 'Incorreta. Uma unica zona de disponibilidade dentro de uma unica regiao nao envolve replicacao entre regioes distintas, o que contraria o cenario descrito.', 2),
  ('75000000-0000-4000-8000-000000000071', '64000000-0000-4000-8000-000000000018', 'A reducao do numero de datacenters utilizados pela aplicacao, para simplificar a estrategia de recuperacao de desastres.', false, 'Incorreta. Reduzir o numero de datacenters utilizados nao contribui para uma estrategia de replicacao entre regioes distintas.', 3),
  ('75000000-0000-4000-8000-000000000072', '64000000-0000-4000-8000-000000000018', 'A escolha de um unico fornecedor de energia eletrica para todos os datacenters utilizados pela aplicacao.', false, 'Incorreta. A escolha de um fornecedor de energia eletrica nao e um conceito relevante para a estrategia de replicacao entre regioes do Azure.', 4),
  ('75000000-0000-4000-8000-000000000073', '64000000-0000-4000-8000-000000000019', 'Uma regiao publica comum do Azure, compartilhada com qualquer outro cliente comercial, sem qualquer isolamento adicional.', false, 'Incorreta. Uma regiao publica comum, compartilhada amplamente com clientes comerciais, pode nao atender as exigencias rigidas de isolamento do cenario descrito.', 1),
  ('75000000-0000-4000-8000-000000000074', '64000000-0000-4000-8000-000000000019', 'Uma regiao soberana do Azure, projetada especificamente para atender requisitos legais e regulatorios rigidos de determinados governos ou setores.', true, 'Correta. Uma regiao soberana, projetada para atender requisitos legais e regulatorios rigidos de determinados governos, e a mais relevante para esse cenario de dados sensiveis do setor publico.', 2),
  ('75000000-0000-4000-8000-000000000075', '64000000-0000-4000-8000-000000000019', 'Uma unica maquina virtual isolada, hospedada por um unico administrador, sem qualquer infraestrutura adicional do Azure envolvida.', false, 'Incorreta. Uma unica maquina virtual isolada nao representa uma oferta especifica do Azure voltada a requisitos regulatorios rigidos de governos.', 3),
  ('75000000-0000-4000-8000-000000000076', '64000000-0000-4000-8000-000000000019', 'Um unico datacenter fisico, escolhido aleatoriamente entre as opcoes disponiveis globalmente, sem qualquer criterio de conformidade.', false, 'Incorreta. Escolher um datacenter aleatoriamente, sem qualquer criterio de conformidade, nao atende as exigencias regulatorias especificas do cenario.', 4),
  ('75000000-0000-4000-8000-000000000077', '64000000-0000-4000-8000-000000000020', 'Pares de regioes e regioes soberanas sao exatamente o mesmo conceito, podendo ser utilizados de forma intercambiavel para qualquer uma das duas necessidades.', false, 'Incorreta. Pares de regioes e regioes soberanas sao conceitos distintos, voltados a objetivos diferentes, e nao devem ser tratados como intercambiaveis.', 1),
  ('75000000-0000-4000-8000-000000000078', '64000000-0000-4000-8000-000000000020', 'Pares de regioes sao mais adequados para a estrategia de recuperacao de desastres da aplicacao comercial, ja que associam duas regioes publicas para fins de replicacao, enquanto regioes soberanas sao mais adequadas para o sistema governamental, por oferecerem isolamento e conformidade regulatoria especificos.', true, 'Correta. Pares de regioes atendem a necessidade de replicacao entre regioes publicas para recuperacao de desastres, enquanto regioes soberanas atendem a exigencias de isolamento e conformidade regulatoria de sistemas governamentais.', 2),
  ('75000000-0000-4000-8000-000000000079', '64000000-0000-4000-8000-000000000020', 'Regioes soberanas devem ser utilizadas exclusivamente para a aplicacao comercial, enquanto pares de regioes devem ser utilizados exclusivamente para o sistema governamental.', false, 'Incorreta. Essa e a inversao dos conceitos: pares de regioes atendem melhor a recuperacao de desastres comercial, enquanto regioes soberanas atendem a exigencias regulatorias governamentais.', 3),
  ('75000000-0000-4000-8000-000000000080', '64000000-0000-4000-8000-000000000020', 'Nenhum dos dois conceitos e relevante para essas necessidades, devendo a equipe considerar exclusivamente o custo de cada regiao disponivel.', false, 'Incorreta. Tanto pares de regioes quanto regioes soberanas sao conceitos diretamente relevantes para as duas necessidades descritas, alem do fator custo.', 4),
  ('75000000-0000-4000-8000-000000000081', '64000000-0000-4000-8000-000000000021', 'Uma entidade gerenciavel individual disponibilizada pelo Azure, como uma maquina virtual, um banco de dados ou uma conta de armazenamento.', true, 'Correta. Um recurso no Azure e qualquer entidade gerenciavel individual, como uma maquina virtual, um banco de dados ou uma conta de armazenamento.', 1),
  ('75000000-0000-4000-8000-000000000082', '64000000-0000-4000-8000-000000000021', 'Um documento fisico impresso, entregue mensalmente pela Microsoft aos clientes corporativos do Azure.', false, 'Incorreta. Um documento fisico impresso nao e um conceito relacionado a recursos dentro do Azure.', 2),
  ('75000000-0000-4000-8000-000000000083', '64000000-0000-4000-8000-000000000021', 'Uma ferramenta de linha de comando utilizada exclusivamente para gerenciar contas de usuario administrativas.', false, 'Incorreta. Uma ferramenta de linha de comando nao e o conceito de recurso; recurso e uma entidade gerenciavel dentro do Azure.', 3),
  ('75000000-0000-4000-8000-000000000084', '64000000-0000-4000-8000-000000000021', 'Um conjunto de politicas de seguranca aplicadas exclusivamente a uma unica regiao geografica do Azure.', false, 'Incorreta. Um conjunto de politicas de seguranca nao e o conceito de recurso; recurso refere-se a uma entidade gerenciavel individual.', 4),
  ('75000000-0000-4000-8000-000000000085', '64000000-0000-4000-8000-000000000022', 'Um contêiner logico utilizado para agrupar e gerenciar recursos relacionados do Azure, como maquinas virtuais e bancos de dados de um mesmo projeto.', true, 'Correta. Um grupo de recursos e um conteiner logico que agrupa recursos relacionados, facilitando seu gerenciamento conjunto dentro do Azure.', 1),
  ('75000000-0000-4000-8000-000000000086', '64000000-0000-4000-8000-000000000022', 'Um servidor fisico especifico, localizado dentro de um unico datacenter do Azure, dedicado a um unico cliente.', false, 'Incorreta. Um grupo de recursos nao e um servidor fisico especifico; e um conceito logico de organizacao dentro do Azure.', 2),
  ('75000000-0000-4000-8000-000000000087', '64000000-0000-4000-8000-000000000022', 'Uma ferramenta de linha de comando exclusiva para monitorar o desempenho de aplicacoes hospedadas no Azure.', false, 'Incorreta. Um grupo de recursos nao e uma ferramenta de monitoramento; e um conteiner logico para organizar recursos.', 3),
  ('75000000-0000-4000-8000-000000000088', '64000000-0000-4000-8000-000000000022', 'Um tipo especifico de licenca de software necessaria para utilizar qualquer servico do Azure.', false, 'Incorreta. Um grupo de recursos nao esta relacionado a licencas de software; e um conceito de organizacao logica de recursos.', 4),
  ('75000000-0000-4000-8000-000000000089', '64000000-0000-4000-8000-000000000023', 'Criar um unico grupo de recursos para toda a assinatura, incluindo os recursos dos tres projetos misturados entre si.', false, 'Incorreta. Misturar os recursos dos tres projetos em um unico grupo de recursos dificultaria o gerenciamento e a aplicacao de politicas independentes para cada projeto.', 1),
  ('75000000-0000-4000-8000-000000000090', '64000000-0000-4000-8000-000000000023', 'Criar um grupo de recursos separado para cada um dos tres projetos, agrupando dentro de cada grupo apenas os recursos relacionados aquele projeto especifico.', true, 'Correta. Criar um grupo de recursos separado para cada projeto permite gerenciar, monitorar e aplicar politicas de forma independente para os recursos de cada um deles.', 2),
  ('75000000-0000-4000-8000-000000000091', '64000000-0000-4000-8000-000000000023', 'Criar uma nova assinatura completamente separada do Azure para cada um dos tres projetos, mesmo que isso aumente a complexidade administrativa.', false, 'Incorreta. Criar novas assinaturas separadas e uma abordagem mais complexa; grupos de recursos ja permitem essa organizacao dentro da mesma assinatura.', 3),
  ('75000000-0000-4000-8000-000000000092', '64000000-0000-4000-8000-000000000023', 'Nao utilizar nenhum tipo de agrupamento, gerenciando cada recurso individualmente sem qualquer organizacao logica entre eles.', false, 'Incorreta. Nao utilizar nenhum tipo de agrupamento tornaria o gerenciamento independente dos recursos de cada projeto mais dificil e desorganizado.', 4),
  ('75000000-0000-4000-8000-000000000093', '64000000-0000-4000-8000-000000000024', 'Apenas o grupo de recursos em si e removido, mas todos os recursos que estavam dentro dele continuam funcionando normalmente de forma independente.', false, 'Incorreta. Ao excluir um grupo de recursos, os recursos contidos nele geralmente sao excluidos junto, e nao continuam funcionando de forma independente.', 1),
  ('75000000-0000-4000-8000-000000000094', '64000000-0000-4000-8000-000000000024', 'Todos os recursos contidos no grupo de recursos, como a maquina virtual, o banco de dados e a conta de armazenamento, sao excluidos juntamente com o grupo de recursos.', true, 'Correta. Excluir um grupo de recursos geralmente exclui tambem todos os recursos contidos nele, incluindo maquinas virtuais, bancos de dados e contas de armazenamento.', 2),
  ('75000000-0000-4000-8000-000000000095', '64000000-0000-4000-8000-000000000024', 'Nenhum recurso e afetado pela exclusao do grupo de recursos, ja que grupos de recursos sao apenas rotulos sem qualquer efeito pratico.', false, 'Incorreta. Grupos de recursos nao sao apenas rotulos sem efeito pratico; excluir um grupo de recursos tem impacto direto sobre os recursos contidos nele.', 3),
  ('75000000-0000-4000-8000-000000000096', '64000000-0000-4000-8000-000000000024', 'Apenas a maquina virtual e excluida, enquanto o banco de dados e a conta de armazenamento permanecem intactos automaticamente.', false, 'Incorreta. A exclusao de um grupo de recursos geralmente afeta todos os recursos contidos nele, e nao apenas um tipo especifico de recurso.', 4),
  ('75000000-0000-4000-8000-000000000097', '64000000-0000-4000-8000-000000000025', 'Misturar todos os recursos de todos os ambientes em um unico grupo de recursos, eliminando qualquer separacao entre desenvolvimento, teste e producao.', false, 'Incorreta. Misturar todos os ambientes em um unico grupo de recursos tornaria ainda mais dificil gerenciar e excluir recursos de forma segura e isolada.', 1),
  ('75000000-0000-4000-8000-000000000098', '64000000-0000-4000-8000-000000000025', 'Planejar cuidadosamente as dependencias entre recursos ao organizar os grupos de recursos, evitando que recursos de um ambiente, como teste, dependam diretamente de recursos localizados em outro grupo, como producao.', true, 'Correta. Planejar cuidadosamente as dependencias entre recursos, evitando que um ambiente dependa diretamente de recursos em outro grupo, e a pratica mais adequada para evitar esse tipo de problema.', 2),
  ('75000000-0000-4000-8000-000000000099', '64000000-0000-4000-8000-000000000025', 'Excluir imediatamente o grupo de recursos de producao, resolvendo assim a dependencia identificada no ambiente de teste.', false, 'Incorreta. Excluir o grupo de recursos de producao causaria uma interrupcao grave no ambiente que esta efetivamente em uso pelos clientes.', 3),
  ('75000000-0000-4000-8000-000000000100', '64000000-0000-4000-8000-000000000025', 'Ignorar completamente a dependencia identificada, ja que dependencias entre grupos de recursos nunca causam qualquer problema pratico.', false, 'Incorreta. Dependencias entre grupos de recursos podem, sim, causar problemas praticos, como o dificultado na exclusao segura descrito no cenario.', 4);
